package net.minecraft.world.level.levelgen.synth;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import net.minecraft.util.RandomSource;
import net.minecraft.world.level.levelgen.PositionalRandomFactory;
import org.junit.jupiter.api.Test;

/** Observable seed-constructor boundaries; no copied permutation algorithm. */
class NoiseConstructorContractTest {
 static final class Source implements RandomSource {
  final RandomSource actual=RandomSource.create(42);final List<String> calls=new ArrayList<>();int doubles,ints;int throwDouble=-1,throwInt=-1;Integer firstInt;double[] scripted;Runnable callback;final RuntimeException failure=new RuntimeException("actual random");
  public double nextDouble(){calls.add("double");int n=++doubles;if(n==throwDouble)throw failure;Runnable work=callback;if(work!=null){callback=null;work.run();}return scripted==null?actual.nextDouble():scripted[n-1];}
  public int nextInt(int bound){calls.add("int:"+bound);if(++ints==throwInt)throw failure;if(ints==1&&firstInt!=null)return firstInt;return actual.nextInt(bound);}
  public RandomSource fork(){throw new AssertionError("unexpected fork");}public PositionalRandomFactory forkPositional(){throw new AssertionError("unexpected positional fork");}public void setSeed(long seed){throw new AssertionError("unexpected setSeed");}public int nextInt(){throw new AssertionError("unexpected unbounded int");}public long nextLong(){return actual.nextLong();}public boolean nextBoolean(){throw new AssertionError("unexpected boolean");}public float nextFloat(){throw new AssertionError("unexpected float");}public double nextGaussian(){throw new AssertionError("unexpected gaussian");}
 }
 static void shape(Source s){assertEquals(259,s.calls.size());assertEquals(List.of("double","double","double"),s.calls.subList(0,3));for(int i=0;i<256;i++)assertEquals("int:"+(256-i),s.calls.get(i+3));}
 @Test void improvedConsumesTheActualThreeOffsetsThenDescendingBounds(){var s=new Source();var noise=new ImprovedNoise(s);shape(s);var expected=RandomSource.create(42);assertEquals(Double.doubleToRawLongBits(expected.nextDouble()*256),Double.doubleToRawLongBits(noise.xo));assertEquals(Double.doubleToRawLongBits(expected.nextDouble()*256),Double.doubleToRawLongBits(noise.yo));assertEquals(Double.doubleToRawLongBits(expected.nextDouble()*256),Double.doubleToRawLongBits(noise.zo));for(int i=256;i>0;i--)expected.nextInt(i);assertEquals(expected.nextLong(),s.nextLong());}
 @Test void simplexConsumesTheSameRngContract(){var s=new Source();new SimplexNoise(s);shape(s);var expected=RandomSource.create(42);for(int i=0;i<3;i++)expected.nextDouble();for(int i=256;i>0;i--)expected.nextInt(i);assertEquals(expected.nextLong(),s.nextLong());}
 @Test void actualRandomFailureStopsAtTheSecondOffset(){for(boolean simplex:new boolean[]{false,true}){var s=new Source();s.throwDouble=2;assertSame(s.failure,assertThrows(RuntimeException.class,()->{if(simplex)new SimplexNoise(s);else new ImprovedNoise(s);}));assertEquals(List.of("double","double"),s.calls);}}
 @Test void actualBoundedFailureKeepsItsCompletedPrefix(){for(boolean simplex:new boolean[]{false,true}){var s=new Source();s.throwInt=57;assertSame(s.failure,assertThrows(RuntimeException.class,()->{if(simplex)new SimplexNoise(s);else new ImprovedNoise(s);}));assertEquals(60,s.calls.size());assertEquals("int:200",s.calls.getLast());}}
 @Test void reentrantConstructionUsesTheSameActualRandomObject(){var s=new Source();var inner=new ArrayList<SimplexNoise>();s.callback=()->inner.add(new SimplexNoise(s));new ImprovedNoise(s);assertEquals(1,inner.size());assertEquals(518,s.calls.size());assertEquals(6,s.doubles);assertEquals(512,s.ints);}
 @Test void simplexUpperHalfIsARealConstructorBoundary(){var s=new Source();s.firstInt=256;assertDoesNotThrow(()->new SimplexNoise(s));shape(s);var improved=new Source();improved.firstInt=256;var failure=assertThrows(ArrayIndexOutOfBoundsException.class,()->new ImprovedNoise(improved));assertEquals("Index 256 out of bounds for length 256",failure.getMessage());assertEquals(4,improved.calls.size());}
 @Test void invalidSimplexIndexKeepsItsActualArrayLength(){var s=new Source();s.firstInt=512;var failure=assertThrows(ArrayIndexOutOfBoundsException.class,()->new SimplexNoise(s));assertEquals("Index 512 out of bounds for length 512",failure.getMessage());assertEquals(4,s.calls.size());}
 @Test void constructionDoesNotEagerlyValidateUnusualOffsets(){for(boolean simplex:new boolean[]{false,true}){var s=new Source();s.scripted=new double[]{Double.NaN,Double.POSITIVE_INFINITY,-1};if(simplex){var noise=new SimplexNoise(s);assertTrue(Double.isNaN(noise.xo));assertEquals(Double.POSITIVE_INFINITY,noise.yo);assertEquals(-256,noise.zo);}else{var noise=new ImprovedNoise(s);assertTrue(Double.isNaN(noise.xo));assertEquals(Double.POSITIVE_INFINITY,noise.yo);assertEquals(-256,noise.zo);}shape(s);}}
 @Test void nullSourceKeepsTheOriginalHelpfulFailure(){for(boolean simplex:new boolean[]{false,true}){var failure=assertThrows(NullPointerException.class,()->{if(simplex)new SimplexNoise(null);else new ImprovedNoise(null);});assertEquals("Cannot invoke \"net.minecraft.util.RandomSource.nextDouble()\" because \"randomSource\" is null",failure.getMessage());}}
 @Test void publicOffsetsKeepRawFloatingPointResults(){for(boolean simplex:new boolean[]{false,true}){var source=new Source();source.scripted=new double[]{Double.longBitsToDouble(0x7ff8123456789abcL),-0.0,Double.MIN_VALUE};double[] expected=source.scripted.clone();double[] actual;if(simplex){var noise=new SimplexNoise(source);actual=new double[]{noise.xo,noise.yo,noise.zo};}else{var noise=new ImprovedNoise(source);actual=new double[]{noise.xo,noise.yo,noise.zo};}for(int n=0;n<3;n++)assertEquals(Double.doubleToRawLongBits(expected[n]*256.0),Double.doubleToRawLongBits(actual[n]));shape(source);}}
}
